package com.example.onlineshop.catalog.domain;
import java.time.Instant;import java.util.*;
public final class CatalogProduct {
 private final UUID id;private final UUID legacyId;private final String slug;private final String name;private final String description;private LifecycleStatus status;private final UUID createdBy;private UUID updatedBy;private final Instant createdAt;private Instant updatedAt;private final long persistedVersion;private long version;private final List<ProductSku> skus=new ArrayList<>();private final Map<UUID,List<AttributeValue>> attributes=new HashMap<>();private final Set<UUID> categoryIds=new HashSet<>();
 public CatalogProduct(UUID id,UUID legacyId,String slug,String name,String description,LifecycleStatus status,UUID createdBy,UUID updatedBy,Instant createdAt,Instant updatedAt,long version){this.id=Objects.requireNonNull(id);this.legacyId=legacyId;this.slug=trimmed(slug,180);this.name=preserved(name,160);if(description==null)throw new ProductValidationException("description is required");this.description=description;this.status=Objects.requireNonNull(status);this.createdBy=createdBy;this.updatedBy=updatedBy;this.createdAt=Objects.requireNonNull(createdAt);this.updatedAt=Objects.requireNonNull(updatedAt);if(updatedAt.isBefore(createdAt)||version<0)throw new ProductValidationException("invalid audit metadata");this.persistedVersion=version;this.version=version;}
 public void addSku(ProductSku sku){status.requireMutable("product");if(skus.stream().anyMatch(s->s.sku().equals(sku.sku())))throw new ProductValidationException("duplicate SKU");skus.add(sku);validateInvariants();}
 public void restoreSku(ProductSku sku){skus.add(sku);validateInvariants();}
 public void assign(ProductAttribute attribute,AttributeValue value){status.requireMutable("product");attribute.requireAssignable();if(!attribute.scope().permitsProduct())throw new ProductValidationException("attribute does not permit product scope");if(!attribute.id().equals(value.attributeId())||attribute.dataType()!=value.dataType())throw new ProductValidationException("attribute value mismatch");var values=attributes.computeIfAbsent(attribute.id(),x->new ArrayList<>());if(values.stream().anyMatch(v->v.id().equals(value.id())))throw new ProductValidationException("duplicate product attribute assignment");values.add(value);}
 public void assignSku(UUID skuId,ProductAttribute attribute,AttributeValue value){status.requireMutable("product");var sku=skus.stream().filter(s->s.id().equals(skuId)).findFirst().orElseThrow(()->new ProductValidationException("unknown SKU"));sku.assign(attribute,value);validateInvariants();}public void addCategory(UUID categoryId){status.requireMutable("product");categoryIds.add(Objects.requireNonNull(categoryId));}
 public void restoreAssignment(ProductAttribute attribute,AttributeValue value){attributes.computeIfAbsent(attribute.id(),x->new ArrayList<>()).add(value);}public void restoreCategory(UUID categoryId){categoryIds.add(categoryId);}
 public ProductSku defaultSku(){return skus.stream().filter(ProductSku::defaultSku).findFirst().orElseThrow(()->new ProductValidationException("product requires a default SKU"));}public void validateInvariants(){if(skus.stream().filter(ProductSku::defaultSku).count()>1)throw new ProductValidationException("only one default SKU is permitted");var signatures=new HashSet<String>();for(var sku:skus)if(!signatures.add(sku.variantSignature()))throw new ProductValidationException("duplicate variant combination");}
 public void activate(UUID actor,Instant now,long expectedVersion){transition(LifecycleStatus.ACTIVE,actor,now,expectedVersion);}public void deactivate(UUID actor,Instant now,long expectedVersion){transition(LifecycleStatus.DRAFT,actor,now,expectedVersion);}public void archive(UUID actor,Instant now,long expectedVersion){if(status==LifecycleStatus.ARCHIVED)throw new ProductValidationException("product is archived");checkVersion(expectedVersion);for(var sku:skus)if(sku.status()!=LifecycleStatus.ARCHIVED)sku.archive(sku.version());status=LifecycleStatus.ARCHIVED;touch(actor,now);}private void transition(LifecycleStatus next,UUID actor,Instant now,long expected){if(status==LifecycleStatus.ARCHIVED)throw new ProductValidationException("archived product cannot transition");checkVersion(expected);if(status==next)return;status=next;touch(actor,now);}private void checkVersion(long expected){if(version!=expected)throw new OptimisticConflictException();}private void touch(UUID actor,Instant now){updatedBy=actor;updatedAt=Objects.requireNonNull(now);if(updatedAt.isBefore(createdAt))throw new ProductValidationException("invalid update time");version++;}
 public UUID id(){return id;}public UUID legacyId(){return legacyId;}public String slug(){return slug;}public String name(){return name;}public String description(){return description;}public LifecycleStatus status(){return status;}public UUID createdBy(){return createdBy;}public UUID updatedBy(){return updatedBy;}public Instant createdAt(){return createdAt;}public Instant updatedAt(){return updatedAt;}public long persistedVersion(){return persistedVersion;}public long version(){return version;}public List<ProductSku> skus(){return List.copyOf(skus);}public Map<UUID,List<AttributeValue>> attributes(){var copy=new HashMap<UUID,List<AttributeValue>>();attributes.forEach((k,v)->copy.put(k,List.copyOf(v)));return Map.copyOf(copy);}public Set<UUID> categoryIds(){return Set.copyOf(categoryIds);}
 private static String trimmed(String s,int max){if(s==null||s.isBlank()||s.length()>max)throw new ProductValidationException("invalid product text");return s.trim();}private static String preserved(String s,int max){if(s==null||s.isBlank()||s.length()>max)throw new ProductValidationException("invalid product text");return s;}
}
